from pathlib import Path
import json,re
home=Path.home()
tid='DEV-PRED-A2Z-REVIEW-CALL-REPAIR-20261005-E042'
state_path=home/'.local/state/prediction-project-executor'/(tid+'.json')
state=json.loads(state_path.read_text()) if state_path.is_file() and not state_path.is_symlink() else {}
evidence=[]
base=home/'.local/share/prediction-chat-bridge'
for folder in ('sent','inflight','outbox'):
    directory=base/folder
    if not directory.is_dir():
        continue
    for p in sorted(directory.glob('*.json'),key=lambda p:p.name,reverse=True)[:500]:
        if p.is_symlink() or not p.is_file() or p.stat().st_size>2000000:
            continue
        try:
            obj=json.loads(p.read_text())
        except (ValueError,OSError):
            continue
        msg=str(obj.get('message') or '')
        if ('DEV_TASK_ID='+tid) not in msg and ('PROJECT_TASK_ID='+tid) not in msg:
            continue
        errors=[line.strip() for line in msg.splitlines() if line.startswith('ERROR=') or 'PermissionError:' in line or line.startswith('DEV_TASK_STATUS=')]
        evidence.append({'event_file':p.name,'errors':errors[-4:]})
cache=home/'.codex/models_cache.json'
models=[]
if cache.is_file() and not cache.is_symlink():
    data=json.loads(cache.read_text())
    models=[{'slug':m.get('slug'),'display_name':m.get('display_name')} for m in data.get('models',[]) if m.get('visibility')=='list']
sol=[m for m in models if str(m.get('display_name') or '').strip().casefold()=='gpt-5.6 sol']
astra=[m for m in models if str(m.get('display_name') or '').strip().casefold()=='gpt-6 astra']
report={'repair_task':tid,'repair_state':state,'repair_events':evidence,'available_model_metadata':models,'required_sol_matches':sol,'required_astra_matches':astra,'production_modified':False,'scout_repeated':False,'full_chain_pass':False}
out=Path.cwd()/'diagnostic-result'
out.mkdir(exist_ok=True)
(out/'resume-evidence.json').write_text(json.dumps(report,indent=2))
proven=state.get('status')=='PASS' and state.get('operation_count')==8 and state.get('source_commit')=='0f0f954a0cffbed95c55a904fec8c5ef8f30f223'
reasons=' '.join(line for e in evidence for line in e['errors'])
if 'blocked write outside task roots' in reasons:
    reason='SHARED_COORDINATOR_OUTSIDE_EXECUTOR_WRITE_SCOPE'
elif reasons:
    reason=reasons[-160:]
else:
    reason='NO_COMPLETED_REPAIR_EVIDENCE' if not proven else 'REPAIR_VERIFIED'
compact={'repair':state.get('status','MISSING'),'proven':proven,'sol':len(sol),'astra':len(astra),'reason':reason}
print('A2Z_RESUME '+json.dumps(compact,separators=(',',':')),flush=True)
raise SystemExit(0 if proven and len(sol)==1 and len(astra)==1 else 1)
